/**
 * ZenCanvas: the single, immutable showcase page.
 *
 * DO NOT EDIT THIS FILE TO CREATE A THEME. Themes are plain CSS files scoped
 * to [data-zen-theme="<name>"] (see src/themes). Everything a theme author
 * needs is exposed as a hook below:
 *   - data-zen-root / data-zen-stage / data-zen-area="hero|essay|controls|sidebar"
 *   - data-zen-title / data-zen-subtitle / data-zen-quote
 *   - shadcn slots such as [data-slot="card"], [data-slot="button"], ...
 */
import { ArrowRight, Sparkles } from 'lucide-react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Switch } from '@/components/ui/switch'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'

const RULES = [
  'Only add a CSS file. Never touch the markup.',
  'Scope every selector to [data-zen-theme="your-name"].',
  'Restyle through tokens first, then [data-slot] hooks.',
  'Choreograph layout with grid-template-areas on [data-zen-stage].',
  'Register the theme once in src/themes/index.ts.',
]

export function ZenCanvas() {
  return (
    <div data-zen-root>
      <main data-zen-stage>
        <header data-zen-area="hero">
          <div className="flex flex-wrap items-center gap-2">
            <Badge>
              <Sparkles className="size-3" /> Prototype
            </Badge>
            <Badge variant="secondary">One markup</Badge>
            <Badge variant="outline">Infinite themes</Badge>
          </div>
          <h1 data-zen-title>The Zen Garden, rebuilt in components.</h1>
          <p data-zen-subtitle>
            A single static React tree, restyled end to end by nothing but a stylesheet: colour,
            type, radius, shadow, component slots and the grid itself.
          </p>
        </header>

        <section data-zen-area="essay">
          <Card data-zen-card>
            <CardHeader>
              <CardDescription>Manifesto</CardDescription>
              <CardTitle className="text-2xl">
                Structure is a promise, style is a conversation
              </CardTitle>
            </CardHeader>
            <CardContent className="flex flex-col gap-4 leading-relaxed">
              <p>
                In 2003 a handful of designers proved that one HTML document could wear a thousand
                faces. Today our documents are component trees, yet the promise still holds: the
                markup says what things are, and the stylesheet decides how they feel.
              </p>
              <blockquote data-zen-quote>
                Make the content stable and the presentation fearless.
              </blockquote>
              <p>
                Semantic data attributes give every theme a handle on the hero, the essay, the
                controls and the sidebar, while shadcn slots expose each primitive for deep
                restyling.
              </p>
            </CardContent>
            <CardFooter className="flex-wrap gap-3">
              <Button>
                Read the guide <ArrowRight className="size-4" />
              </Button>
              <Button variant="secondary">Browse themes</Button>
              <Button variant="outline">Fork a theme</Button>
              <Button variant="ghost">Dismiss</Button>
            </CardFooter>
          </Card>
        </section>

        <section data-zen-area="controls">
          <Card data-zen-card>
            <CardHeader>
              <CardTitle>Controls</CardTitle>
              <CardDescription>Interactive primitives, themed from the outside.</CardDescription>
            </CardHeader>
            <CardContent>
              <Tabs defaultValue="account">
                <TabsList>
                  <TabsTrigger value="account">Account</TabsTrigger>
                  <TabsTrigger value="notifications">Notifications</TabsTrigger>
                  <TabsTrigger value="billing">Billing</TabsTrigger>
                </TabsList>
                <TabsContent value="account" className="flex flex-col gap-4 pt-4">
                  <label className="flex flex-col gap-2 text-sm font-medium">
                    Display name
                    <Input placeholder="Ada Lovelace" defaultValue="Ada Lovelace" />
                  </label>
                  <label className="flex items-center justify-between gap-4 text-sm font-medium">
                    Publish my theme gallery
                    <Switch defaultChecked />
                  </label>
                </TabsContent>
                <TabsContent value="notifications" className="flex flex-col gap-4 pt-4">
                  <label className="flex items-center justify-between gap-4 text-sm font-medium">
                    Weekly digest
                    <Switch />
                  </label>
                  <label className="flex items-center justify-between gap-4 text-sm font-medium">
                    New theme alerts
                    <Switch defaultChecked />
                  </label>
                </TabsContent>
                <TabsContent value="billing" className="pt-4 text-sm text-muted-foreground">
                  Themes are free forever. Contributions are paid in praise.
                </TabsContent>
              </Tabs>
            </CardContent>
            <CardFooter className="gap-3">
              <Button size="sm">Save</Button>
              <Button size="sm" variant="outline">
                Cancel
              </Button>
            </CardFooter>
          </Card>
        </section>

        <aside data-zen-area="sidebar">
          <Card data-zen-card>
            <CardHeader>
              <CardTitle>Contributor rules</CardTitle>
              <CardDescription>Five lines to a new theme.</CardDescription>
            </CardHeader>
            <CardContent>
              <ol className="flex list-decimal flex-col gap-3 pl-5 text-sm leading-relaxed marker:text-primary">
                {RULES.map((rule) => (
                  <li key={rule}>{rule}</li>
                ))}
              </ol>
            </CardContent>
          </Card>
        </aside>
      </main>
    </div>
  )
}
